import arc.Core;
import arc.files.Fi;
import arc.freetype.FreeTypeFontGenerator;
import arc.freetype.FreeTypeFontGenerator.FreeTypeFontParameter;
import arc.graphics.g2d.PixmapPacker;
import arc.graphics.g2d.Font.Glyph;
import arc.mock.MockGL20;
import arc.util.ArcNativesLoader;

import java.io.BufferedOutputStream;
import java.io.DataOutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;

/** Exports the glyphs generated by the official desktop Arc FreeType backend. */
public final class PackUpstreamLogicFont {
    // Pinned Mindustry v160.8 Fonts.java, the "logic" font load parameters.
    private static final String characters =
        "\0ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz1234567890\"!`?'.,;:()[]{}<>|/@\\^$€-%+=#_&~*";

    public static void main(String[] args) throws Exception {
        if (args.length != 2) throw new IllegalArgumentException("Expected original logic.ttf and output file");
        ArcNativesLoader.load();
        Core.gl = Core.gl20 = new MockGL20();
        var generator = new FreeTypeFontGenerator(new Fi(args[0]));
        var packer = new PixmapPacker(256, 128, 2, false);
        packer.setAllowMultiplePages(false);
        var parameter = new FreeTypeFontParameter();
        parameter.size = 16;
        parameter.incremental = false;
        parameter.characters = characters;
        parameter.packer = packer;
        try {
            var font = generator.generateFont(parameter);
            var pixels = packer.getPages().first().getPixmap();
            var data = font.getData();
            var glyphs = new ArrayList<Glyph>();
            for (var page : data.glyphs) {
                if (page == null) continue;
                for (var glyph : page) {
                    if (glyph != null) glyphs.add(glyph);
                }
            }
            try (var out = new DataOutputStream(new BufferedOutputStream(Files.newOutputStream(Path.of(args[1]))))) {
                out.writeInt(0x4d334c31); // M3L1
                out.writeShort(pixels.width);
                out.writeShort(pixels.height);
                out.writeFloat(data.spaceXadvance);
                out.writeFloat(data.lineHeight);
                out.writeFloat(data.capHeight);
                out.writeFloat(data.ascent);
                out.writeShort(glyphs.size());
                for (var glyph : glyphs) {
                    out.writeChar(glyph.id);
                    out.writeShort(glyph.srcX);
                    out.writeShort(glyph.srcY);
                    out.writeShort(glyph.width);
                    out.writeShort(glyph.height);
                    out.writeShort(glyph.xoffset);
                    out.writeShort(glyph.yoffset);
                    out.writeShort(glyph.xadvance);
                }
                for (int y = 0; y < pixels.height; y++) {
                    for (int x = 0; x < pixels.width; x++) out.writeInt(pixels.get(x, y));
                }
            }
        } finally {
            packer.forceDispose();
            generator.dispose();
        }
    }
}
